create table public.quote_share_snapshots (id uuid primary key default gen_random_uuid(), quote_issuance_id uuid not null references public.quote_issuances(id) on delete cascade, owner_user_id uuid not null references auth.users(id) on delete cascade, version integer not null, payload jsonb not null check (jsonb_typeof(payload)='object'), created_at timestamptz not null default now(), unique(quote_issuance_id,version));
create table public.quote_shares (id uuid primary key default gen_random_uuid(), quote_issuance_id uuid not null references public.quote_issuances(id) on delete cascade, snapshot_id uuid not null references public.quote_share_snapshots(id), owner_user_id uuid not null references auth.users(id) on delete cascade, token_hash text not null unique, status text not null check(status in ('PENDING','OPENED','ACCEPTED','REJECTED','REVOKED','SUPERSEDED')), created_at timestamptz not null default now(), first_opened_at timestamptz,last_opened_at timestamptz,responded_at timestamptz,accepted_at timestamptz,rejected_at timestamptz,revoked_at timestamptz,superseded_at timestamptz);
create index quote_shares_owner_idx on public.quote_shares(owner_user_id,created_at); create index quote_shares_issuance_idx on public.quote_shares(quote_issuance_id); create index quote_shares_token_idx on public.quote_shares(token_hash);
alter table public.quote_share_snapshots enable row level security; alter table public.quote_shares enable row level security;
revoke all on public.quote_share_snapshots,public.quote_shares from anon,authenticated; grant select on public.quote_share_snapshots,public.quote_shares to authenticated;
create policy "owners read snapshots" on public.quote_share_snapshots for select to authenticated using((select auth.uid())=owner_user_id); create policy "owners read shares" on public.quote_shares for select to authenticated using((select auth.uid())=owner_user_id);
insert into public.app_config(key,value) values('public_base_url','"https://quotivo.esigenta.it"'::jsonb) on conflict(key) do nothing;
create or replace function public.create_quote_share(p_issuance_id uuid,p_snapshot_payload jsonb) returns table(share_id uuid,issuance_id uuid,version integer,public_url text,status text) language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); v integer; sid uuid; token text:=encode(gen_random_bytes(32),'hex'); base_url text; begin if uid is null then raise exception 'AUTH_REQUIRED'; end if; if not exists(select 1 from public.quote_issuances where id=p_issuance_id and user_id=uid) then raise exception 'NOT_FOUND'; end if; if not exists(select 1 from public.entitlement_grants g where g.user_id=uid and g.access_level='PRO' and g.starts_at<=now() and (g.ends_at is null or g.ends_at>=now()) and g.revoked_at is null) then raise exception 'PRO_REQUIRED'; end if; if jsonb_typeof(p_snapshot_payload)!='object' or p_snapshot_payload='{}'::jsonb then raise exception 'INVALID_SNAPSHOT'; end if; perform pg_advisory_xact_lock(hashtext(p_issuance_id::text)); update public.quote_shares set status='SUPERSEDED',superseded_at=now() where quote_issuance_id=p_issuance_id and owner_user_id=uid and status in('PENDING','OPENED'); select coalesce(max(version),0)+1 into v from public.quote_share_snapshots where quote_issuance_id=p_issuance_id; insert into public.quote_share_snapshots(quote_issuance_id,owner_user_id,version,payload) values(p_issuance_id,uid,v,p_snapshot_payload) returning id into sid; select value#>>'{}' into base_url from public.app_config where key='public_base_url'; insert into public.quote_shares(quote_issuance_id,snapshot_id,owner_user_id,token_hash,status) values(p_issuance_id,sid,uid,encode(digest(token,'sha256'),'hex'),'PENDING') returning id into share_id; issuance_id:=p_issuance_id;version:=v;public_url:=rtrim(coalesce(base_url,''),'/')||'/p/'||token;status:='PENDING';return next;end; $$;
create or replace function public.revoke_quote_share(p_share_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ begin update public.quote_shares set status='REVOKED',revoked_at=now() where id=p_share_id and owner_user_id=auth.uid() and status in('PENDING','OPENED'); return found; end; $$;
revoke all on function public.create_quote_share(uuid,jsonb),public.revoke_quote_share(uuid) from public; grant execute on function public.create_quote_share(uuid,jsonb),public.revoke_quote_share(uuid) to authenticated;
